"""Migrated Meridian CRM 4.2 ACCT_MASTER validation rules."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _value(record: dict | None, field: str) -> Any:
    """Return a field value, treating missing and None values as legacy empty strings."""
    if record is None:
        return ""
    value = record.get(field, "")
    return "" if value is None else value


def _text(record: dict | None, field: str) -> str:
    """Return the legacy string representation used by LEN and code comparisons."""
    value = _value(record, field)
    return value if isinstance(value, str) else str(value)


def _number(value: Any) -> Decimal:
    """Apply legacy numeric coercion: empty values compare as zero."""
    if value is None or value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image in legacy rule-file order."""
    del today  # Present for the fixed interface; unused by these rules.

    errors: list[dict] = []

    # ACC-001: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if len(_text(record, "ACCT_NM")) < 2:
            errors.append(
                {
                    "code": "E1001",
                    "message": "Account name too short",
                    "severity": "BLOCK",
                }
            )

    # ACC-002: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if _text(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            errors.append(
                {
                    "code": "E1002",
                    "message": "Invalid account type",
                    "severity": "BLOCK",
                }
            )

    # ACC-003: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if _number(_value(record, "ANN_REV")) < Decimal("0"):
            errors.append(
                {
                    "code": "E1003",
                    "message": "Annual revenue negative",
                    "severity": "BLOCK",
                }
            )

    # ACC-004: UPDATE only. INSERT OLD values are irrelevant because this rule does not run.
    if event == "UPDATE":
        if (
            _text(old, "CRED_HOLD") == "Y"
            and _text(record, "CRED_HOLD") == "N"
            and _number(_value(record, "CRED_LIMIT")) <= Decimal("0")
        ):
            errors.append(
                {
                    "code": "E1004",
                    "message": "Cannot release credit hold with zero credit limit",
                    "severity": "BLOCK",
                }
            )

    # ACC-005: INSERT, UPDATE
    if event in ("INSERT", "UPDATE"):
        if len(_text(record, "REGION_CD")) != 3:
            errors.append(
                {
                    "code": "E1005",
                    "message": "Region code must be 3 chars",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected legacy validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
